// Incident checklist:
// 1. What users and endpoints are affected?
// 2. Did errors, latency, or dependency failures spike?
// 3. What changed recently?
// 4. Can we rollback, disable a feature flag, or drain work?
// 5. What test or monitor prevents this from returning?

app.MapPost("/reviews/{id}/grade", async (string id, GradeRequest request, IFeatureManager features, IGradingService grading, CancellationToken ct) =>
{
    // Flip the flag off to mitigate without a redeploy.
    var result = await features.IsEnabledAsync("AdaptiveGrading")
        ? await grading.GradeAdaptiveAsync(id, request, ct)
        : await grading.GradeClassicAsync(id, request, ct);

    return Results.Ok(result);
});
